import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    output = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            A = [int(next(iterator)) for _ in range(N)]
            B = [int(next(iterator)) for _ in range(N)]
        except StopIteration:
            break

        pos_map = {}
        for idx, val in enumerate(B):
            if val not in pos_map:
                pos_map[val] = []
            pos_map[val].append(idx)

        current_pos = {}
        for idx, val in enumerate(A):
            if val not in current_pos:
                current_pos[val] = []
            current_pos[val].append(idx)

        target_indices = []
        for val in A:
            targets = current_pos[val]
            if not targets:
                continue
            start_idx = targets.pop(0)
            b_targets = pos_map[val]
            target_idx = b_targets.pop(0)
            target_indices.append((start_idx, target_idx))

        score = 0
        for start, target in target_indices:
            if start < target:
                score += (target - start) * (A[start] - B[target])
            elif start > target:
                score += (start - target) * (A[start] - B[target])

        output.append(str(score))

    sys.stdout.write('\n'.join(output) + '\n')

if __name__ == "__main__":
    solve()
